// indexed key.
export const CONCATENATED_STREET_SUFFIXES = new Set(["allee","brucke","burgermeister","damm","gade","gasse","gata","gatan","gate","gracht","hof","kreuz","laan","markt","platz","plein","quelle","rundwanderweg","siedlung","stiege","straat","strasse","vag","vagen","veien","vej","weg","wiese"]);

